mapper.select:
SELECT d.summary_no AS summaryNo, stay.ward_id AS wardId, stay.ward_name AS wardName, d.location_id AS deptId, loc.name AS deptName, SUM(d.quantity) AS totalQty, COUNT(DISTINCT d.patient_id) AS patientCount, MAX(d.status_enum) AS status, MIN(d.created_at) AS createTime, MAX(d.dispense_time) AS dispenseTime, MAX(prac.name) AS operatorName FROM med_medication_dispense d LEFT JOIN adm_encounter e ON e.id = d.encounter_id AND e.is_deleted = 0 LEFT JOIN adm_location loc ON loc.id = d.location_id AND loc.is_deleted = 0 LEFT JOIN adm_practitioner prac ON prac.id = d.practitioner_id AND prac.is_deleted = 0
WHERE d.is_deleted = 0 AND d.dispense_enum IN ('OUTPATIENT', 'INPATIENT') AND d.summary_no IS NOT NULL
AND d.summary_no LIKE CONCAT('%', #{summaryNo}, '%')
AND stay.ward_id = #{wardId}
AND stay.ward_name LIKE CONCAT('%', #{wardName}, '%')
AND d.status_enum = #{status}
AND d.created_at >= #{createTimeStart}
AND d.created_at <= #{createTimeEnd}
GROUP BY d.summary_no, stay.ward_id, stay.ward_name, d.location_id, loc.name ORDER BY MIN(d.created_at) DESC

SELECT d.patient_id AS patientId, d.encounter_id AS encounterId, p.name AS name, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, p.gender_enum AS genderEnum, p.phone AS phone, MAX(d.status_enum) AS statusEnum, d.dispense_enum AS dispenseEnum, COUNT(d.id) AS drugCount, MAX(d.created_at) AS createdAt FROM med_medication_dispense d JOIN adm_patient p ON p.id = d.patient_id AND p.is_deleted = 0 WHERE d.is_deleted = 0 AND d.dispense_enum = 'REFUND'
AND d.patient_id = #{query.patientId}
AND d.encounter_id = #{query.encounterId}
AND d.status_enum = #{query.statusEnum}
AND p.name LIKE CONCAT('%', #{query.name}, '%')
AND d.created_at >= #{query.startTime}
AND d.created_at <= #{query.endTime}
GROUP BY d.encounter_id, d.patient_id, p.name, p.birth_date, p.gender_enum, p.phone, d.dispense_enum ORDER BY MAX(d.created_at) DESC

SELECT d.id AS id, d.tenant_id AS tenantId, d.bus_no AS busNo, d.status_enum AS statusEnum, d.dispense_enum AS dispenseEnum, d.medication_id AS medicationId, d.patient_id AS patientId, d.encounter_id AS encounterId, d.med_req_id AS medReqId, d.quantity AS quantity, d.unit_code AS unitCode, d.dispense_quantity AS dispenseQuantity, d.lot_number AS lotNumber, d.preparer_id AS preparerId, d.prepare_time AS prepareTime, d.practitioner_id AS practitionerId, d.dispense_time AS dispenseTime, d.dosage_instruction AS dosageInstruction, d.method_code AS methodCode, d.frequency_code AS frequencyCode, d.dose AS dose, d.dose_unit_code AS doseUnitCode, d.summary_no AS summaryNo, md.name AS name, md.merchandise_name AS merchandiseName, md.category_code AS categoryCode, md.total_volume AS totalVolume, md.comprised_text AS comprisedText, md.ingredient AS ingredient, md.approval_number AS approvalNumber, md.skin_test_flag AS skinTestFlag, md.inject_flag AS injectFlag, md.manufacturer_text AS manufacturerText, md.antibiotic_flag AS antibioticFlag, md.rx_flag AS rxFlag, md.dose_form_code AS doseFormCode, md.package_unit_code AS packageUnitCode, md.py_str AS pyStr FROM med_medication_dispense d LEFT JOIN med_medication_definition md ON md.id = d.medication_id AND md.is_deleted = 0 WHERE d.is_deleted = 0 AND d.dispense_enum = 'REFUND'
AND d.patient_id = #{query.patientId}
AND d.encounter_id = #{query.encounterId}
AND d.status_enum = #{query.statusEnum}
AND d.bus_no = #{query.busNo}
ORDER BY d.created_at DESC
